import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"Driving licence and traffic rules","description":"Driving in Qatar on a foreign licence, getting a Qatari licence, checking and paying violations, and reporting a minor accident.","frontmatter":{"title":"Driving licence and traffic rules","description":"Driving in Qatar on a foreign licence, getting a Qatari licence, checking and paying violations, and reporting a minor accident.","lastChecked":"2026-10","sourceCount":9},"headers":[],"relativePath":"guide/driving.md","filePath":"guide/driving.md"}'),i={name:"guide/driving.md"};function n(f,e,s,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="driving-licence-and-traffic-rules" tabindex="-1">Driving licence and traffic rules <a class="header-anchor" href="#driving-licence-and-traffic-rules" aria-label="Permalink to &quot;Driving licence and traffic rules&quot;">​</a></h1><p>The General Directorate of Traffic handles driving licences, and what you need depends on whether you are visiting or living here.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>Non-Qataris and GCC citizens need a legal residence permit in Qatar before they can get a Qatari licence.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="driving-as-a-visitor" tabindex="-1">Driving as a visitor <a class="header-anchor" href="#driving-as-a-visitor" aria-label="Permalink to &quot;Driving as a visitor&quot;">​</a></h2><ul><li>If you are a visitor or foreign tourist with a valid international driving licence, you can drive on it for no more than six months. After that, go to the licensing authority for approval.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>If you live in a GCC country and hold a valid licence from there, you can drive on it for no more than three months when visiting Qatar.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Your passport is used to confirm your date of entry.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>MOI&#39;s list also shows a temporary driving licence for tourists, visitors and foreigners, valid for three months.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li></ul><h2 id="moving-here-with-a-foreign-licence" tabindex="-1">Moving here with a foreign licence <a class="header-anchor" href="#moving-here-with-a-foreign-licence" aria-label="Permalink to &quot;Moving here with a foreign licence&quot;">​</a></h2><p>MOI does not describe a simple swap. If you came to work, hold a residence permit and have a licence from your own country, you are sent to a driving school to take a test that shows you can drive. A committee under the Traffic Department runs the test.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><ul><li>If you pass, you get the licence.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>If you fail, you get one more try. After that, you take a full learning course at the school.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li></ul><h2 id="getting-a-qatari-licence-through-a-driving-school" tabindex="-1">Getting a Qatari licence through a driving school <a class="header-anchor" href="#getting-a-qatari-licence-through-a-driving-school" aria-label="Permalink to &quot;Getting a Qatari licence through a driving school&quot;">​</a></h2><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><ul><li>You must be at least 18 for a light vehicle or motorcycle licence.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li><li>You must be at least 21 for a heavy vehicle licence or for construction and agricultural equipment.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1]</a></sup></li><li>You must meet the physical fitness requirement and pass the driving test.<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1]</a></sup></li></ul><h3 id="what-non-qataris-need" tabindex="-1">What non-Qataris need <a class="header-anchor" href="#what-non-qataris-need" aria-label="Permalink to &quot;What non-Qataris need&quot;">​</a></h3><ul><li>A letter from your sponsor approving the application and naming the licence type.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1]</a></sup></li><li>Your passport and a copy.<sup class="footnote-ref"><a href="#fn1" id="fnref1:13">[1]</a></sup></li><li>A copy of the sponsor&#39;s ID card, if the sponsor is a person.<sup class="footnote-ref"><a href="#fn1" id="fnref1:14">[1]</a></sup></li><li>3 recent colour photos.<sup class="footnote-ref"><a href="#fn1" id="fnref1:15">[1]</a></sup></li></ul><p>You then choose one of the approved driving schools.<sup class="footnote-ref"><a href="#fn1" id="fnref1:16">[1]</a></sup></p><h3 id="where-to-go" tabindex="-1">Where to go <a class="header-anchor" href="#where-to-go" aria-label="Permalink to &quot;Where to go&quot;">​</a></h3><p>Licences are handled at the General Directorate of Traffic and MOI Services Centers. The fees are listed on the same MOI page.<sup class="footnote-ref"><a href="#fn1" id="fnref1:17">[1]</a></sup></p><p>The Traffic department&#39;s contact number is 2344444.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="renewing-your-licence" tabindex="-1">Renewing your licence <a class="header-anchor" href="#renewing-your-licence" aria-label="Permalink to &quot;Renewing your licence&quot;">​</a></h2><ul><li>You can renew online on the Metrash2 app.<sup class="footnote-ref"><a href="#fn1" id="fnref1:18">[1]</a></sup></li><li>A lost or damaged licence can be replaced, and MOI charges the same fee as issuing one.<sup class="footnote-ref"><a href="#fn1" id="fnref1:19">[1]</a></sup></li><li>The Other Inquiries page lets you check when your driving licence expires.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li></ul><h2 id="checking-and-paying-violations" tabindex="-1">Checking and paying violations <a class="header-anchor" href="#checking-and-paying-violations" aria-label="Permalink to &quot;Checking and paying violations&quot;">​</a></h2><ul><li>MOI&#39;s Traffic Services page lets you look up violations recorded on a vehicle.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li>The MOI traffic violations site lets you look up and pay violations using the vehicle number, personal number or establishment registration.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li>If you subscribe to Metrash SMS, you get a traffic violation alert.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li></ul><p>Fees for traffic services such as vehicle registration are on the Traffic Fee page.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><h2 id="reporting-a-minor-accident-on-metrash2" tabindex="-1">Reporting a minor accident on Metrash2 <a class="header-anchor" href="#reporting-a-minor-accident-on-metrash2" aria-label="Permalink to &quot;Reporting a minor accident on Metrash2&quot;">​</a></h2><p>If two vehicles are in a minor accident, you can report it on Metrash2 and not go to traffic investigation in person.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></p><ol><li>Take up to 4 photos of each vehicle, with one showing the number plate clearly.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup></li><li>Move the vehicles away from the road.<sup class="footnote-ref"><a href="#fn8" id="fnref8:2">[8]</a></sup></li><li>Turn on location services on your phone.<sup class="footnote-ref"><a href="#fn8" id="fnref8:3">[8]</a></sup></li><li>Sign in to Metrash2, select Traffic Services and open Accident Report.<sup class="footnote-ref"><a href="#fn8" id="fnref8:4">[8]</a></sup></li><li>Enter the details of both vehicles: vehicle number, QID number and mobile number.<sup class="footnote-ref"><a href="#fn8" id="fnref8:5">[8]</a></sup></li><li>Attach the photos, confirm the data is correct and submit the report for traffic investigation.<sup class="footnote-ref"><a href="#fn8" id="fnref8:6">[8]</a></sup></li><li>Wait for the SMS asking you to expect a second message.<sup class="footnote-ref"><a href="#fn8" id="fnref8:7">[8]</a></sup></li><li>After investigators review the photos, both parties get a text telling them to go to the insurance company or giving approval for vehicle repair.<sup class="footnote-ref"><a href="#fn8" id="fnref8:8">[8]</a></sup></li></ol><p>The Traffic Reports page lets you look up a road accident report or a vehicle repair permit.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><h2 id="traffic-rules" tabindex="-1">Traffic rules <a class="header-anchor" href="#traffic-rules" aria-label="Permalink to &quot;Traffic rules&quot;">​</a></h2><p>The General Directorate of Traffic says the current traffic law was issued in 2007, and its page has a Traffic Signs section.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><p>See also: <a href="./metrash">Metrash</a>, <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./transport">Transport</a>, <a href="./emergencies">Emergencies</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationoftraffic%2Fservices%2Flicensing%2Band%2Bexamination%2Bof%2Bdrivers%2Fserw" target="_blank" rel="noreferrer">Licensing and Inspection of Drivers</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:12" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:13" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:14" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:15" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:16" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:17" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:18" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:19" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/gatraffic" target="_blank" rel="noreferrer">General Administration of Traffic</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/others" target="_blank" rel="noreferrer">Other Inquiries</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/trafficservices" target="_blank" rel="noreferrer">Traffic Services</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Interior, <a href="https://fees2.moi.gov.qa/moipay/inquiry/violation" target="_blank" rel="noreferrer">Pay traffic violations</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/metrash/individualmetrash" target="_blank" rel="noreferrer">Metrash for Individuals</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/gatraffic/!ut/p/z0/fY7LDoIwEEW_hiWZgk-WxBgSTWThuxtTy0BG6QBlon6-jR_g7pzk5uSChgtoNi9qjFDHpg1-1fPbLlN5kpVqWx7ygOvidFxNl6nKUtjDBvT_SWjQYxh0Dtp2LPgRuLyta-keU1DPKDFypEYTV9gbLw5ZbOcciSBGqkFGb1pTOWIaxf--dXWAuiYbKZssZhMF_bM4fwEQv_A-/" target="_blank" rel="noreferrer">Traffic Fee</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/gatraffic/!ut/p/z1/jY_NDoIwEIQfqdOCpBxrNfwUbQytwF5MT4ZE0YPx-SXEq5U9zSbfzGQYsZ7RFN7jNbzGxxRu8z9QdjnmUDy3MNapWe6Ls9epFMgF6xagUjItObiRJSRU62q3tVoAnNEaP36cwjp_BKB4fMdoQepyVyFpYYomS-YFzUELfQLk5gvEJv4red697zFWH0zJlfc!/?1dmy=&amp;urile=wcm:path:/wcmlib-internet-en/sa-departmentcommittee/generaladministrationoftraffic/minor+accident" target="_blank" rel="noreferrer">Minor Accidents Registration via Metrash2</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/trafficservices/trafficreports" target="_blank" rel="noreferrer">Traffic Reports</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',32)])])}const u=a(i,[["render",n]]);export{d as __pageData,u as default};
